import json
W="Sources: publisher and catalogue pages plus a review; not read in full."
def sp(n,leaf,title,authors,cid,why,books):
    c=f"https://covers.openlibrary.org/b/id/{cid}-L.jpg"
    for b in books: b['cover']=c
    json.dump({"leaf":leaf,"title":title,"authors":authors,"cover":c,"why":why,"books":books},open(f'/tmp/mc/spec{n}.json','w'))
sp(506,"oldfangs-fantasy","Twilight Forever Rising",["Lena Meydan"],7928492,"Lena Meydan's Twilight Forever Rising (2010; Open Library, catalogue blurb): a Russian vampire-clan novel in which the empath Darel Ericson of the Dahanavar clan is drawn into the clans' ancient order and feuds. Walk: Speculative fiction > Fantasy > Real earth fantasy > Urban fantasy > Oldfangs fantasy (the vampires are an old, clan-bound people in the modern world). Rejected: Occult institutions (no institution), Romantasy. Wobble: medium, fangs-out vampires. "+W,[{"id":"MC05970","title":"Twilight Forever Rising","year":2010}])
sp(507,"breakaway-space-colonies","A Boy and His Tank",["Leo Frankowski"],406687,"Leo Frankowski's New Kashubia series (A Boy and His Tank 1999, The War With Earth 2003, Kren of the Mitchegai 2004, the last two with Dave Grossman; Baen, PW, reviews): colonists on the world New Kashubia pay off the colony's debt by fighting as virtual-reality mercenaries, then revolt against Earth's rule. Walk: Speculative fiction > Futurist > Spacefaring > Colony life > Colony politics > Breakaway space colonies (the contest is colony against Earth). Rejected: Space navy (the fight is the colony's independence, not a navy arc), Space mercenaries. Wobble: medium, military SF. "+W,[{"id":"MC05975","title":"A Boy and His Tank","year":1999},{"id":"MC05981","title":"The War With Earth","year":2003},{"id":"MC05979","title":"Kren of the Mitchegai","year":2004}])
sp(508,"lost-race","The Fata Morgana",["Leo Frankowski"],406711,"Leo Frankowski's The Fata Morgana (1999; Baen, PW, one review): a floating western-isles realm of hidden people found by outsiders. Walk: Speculative fiction > Fantastic > Lost world fiction > Lost race (hidden people with their own rulers and customs). Rejected: Fantastic voyage (the journey is not the story). Wobble: medium. "+W,[{"id":"MC05980","title":"The Fata Morgana","year":1999}])
